        Button inspectScene=new Button("Propiedades y script"),addScene=new Button("＋ Escena"),removeScene=new Button("Eliminar");inspectScene.setMaxWidth(Double.MAX_VALUE);inspectScene.setOnAction(e->selectSceneTarget());addScene.setOnAction(e->addScene());removeScene.setOnAction(e->removeScene());

