        Button addLayer=new Button("＋ Capa"),deleteLayer=new Button("Eliminar"),back=new Button("Enviar atrás"),front=new Button("Traer delante"),layerSettings=new Button("Capas y matriz de colisiones…");addLayer.setOnAction(e->addTileLayer());deleteLayer.setOnAction(e->deleteTileLayer());back.setOnAction(e->moveTileLayer(-1));front.setOnAction(e->moveTileLayer(1));layerSettings.setMaxWidth(Double.MAX_VALUE);layerSettings.setOnAction(e->LayerSettingsDialog.show(app.owner(),app.project(),()->{refreshTileLayers(true);rebuildInspector();redraw();app.changed();}));

